import { cacheTag } from 'next/cache';
import { revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

async function ProductListing() {
  'use cache';
  cacheTag('products');

  const products = await getAllProducts();

  return (
    <ul className="space-y-2">
      {products.map((product) => (
        <li
          key={product.id}
          className="flex justify-between rounded-lg border border-gray-200 bg-white px-4 py-3 shadow-sm"
        >
          <span className="font-medium">{product.name}</span>
          <span className="text-gray-600">${product.price}</span>
        </li>
      ))}
    </ul>
  );
}

export default function Page() {
  async function invalidateProductsCache() {
    'use server';
    revalidateTag('products', 'max');
  }

  return (
    <div className="mx-auto max-w-2xl space-y-8 p-8">
      <h1 className="text-2xl font-bold">Product Listing</h1>

      <ProductListing />

      <form action={invalidateProductsCache} className="space-y-4">
        <p className="text-sm text-gray-600">
          Product data is cached for performance. After adding or updating
          products, invalidate the cache to see fresh data.
        </p>
        <button
          type="submit"
          className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2"
        >
          Invalidate Products Cache
        </button>
      </form>
    </div>
  );
}

